refsection.programlisting:
// example #4: non-rectangular (polar) grid
function Z = saddle(X, Y)
    Z = X.^2-Y.^2;
endfunction

nr = 40; ntheta = 80;
r     = linspace(0.5, 1, nr);
theta = linspace(0, 2*%pi, ntheta);
[R, T] = ndgrid(r, theta);
X = R .* cos(T);
Y = R .* sin(T);

clf()
gcf().color_map = jet(128);
colorbar(-1,1)
Sfgrayplot(X, Y, saddle, strf="041")
xtitle("Non-rectangular polar grid: z=x^2-y^2")

